  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider, useTheme } from './ThemeContext';
  3→import { LanguageProvider, useTranslation } from './LanguageContext';
  4→import { AgentProvider } from './AgentContext';
  5→import { FileUpload } from './components/FileUpload';
  6→import { QueryEditor } from './components/QueryEditor';
  7→import { ResultsTable } from './components/ResultsTable';
  8→import { ResultMarkdown } from './components/ResultMarkdown';
  9→import { Sidebar } from './components/Sidebar';
 10→import { ErrorMessage } from './components/ErrorMessage';
 11→import { AgentPanel } from './components/AgentPanel';
 12→import type { TableInfo, QueryResult, LangfuseStatus } from './types';
 13→import './App.css';
 14→
 15→function AppContent({ tables, refreshTables, langfuseStatus }: { tables: TableInfo[]; refreshTables: () => Promise<void>; langfuseStatus: LangfuseStatus }) {
 16→  const { theme, toggleTheme } = useTheme();
 17→  const { language, setLanguage, t } = useTranslation();
 18→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 19→  const [error, setError] = useState<string | null>(null);
 20→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 21→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 22→  );
 23→  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
 24→  const [agentOpen, setAgentOpen] = useState(false);
 25→
 26→  const handleAgentToggle = () => {
 27→    setAgentOpen((prev) => !prev);
 28→  };
 29→
 30→  const handleLoadSample = useCallback(async () => {
 31→    setError(null);
 32→    try {
 33→      const response = await fetch('/api/upload/sample', { method: 'POST' });
 34→      if (!response.ok) throw new Error('Failed to load sample dataset');
 35→      await refreshTables();
 36→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 37→    } catch (e) {
 38→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 39→    }
 40→  }, [refreshTables]);
 41→
 42→  const handleFileUpload = useCallback(
 43→    async (file: File) => {
 44→      setError(null);
 45→      try {
 46→        const formData = new FormData();
 47→        formData.append('file', file);
 48→        const response = await fetch('/api/upload', {
 49→          method: 'POST',
 50→          body: formData,
 51→        });
 52→        if (!response.ok) throw new Error('Failed to upload file');
 53→        const result = await response.json();
 54→        await refreshTables();
 55→        setEditorQuery(`SELECT * FROM "${result.name}" LIMIT 100`);
 56→      } catch (e) {
 57→        setError(e instanceof Error ? e.message : 'Failed to upload file');
 58→      }
 59→    },
 60→    [refreshTables]
 61→  );
 62→
 63→  const handleQueryExecute = useCallback(
 64→    async (sql: string) => {
 65→      setError(null);
 66→      setQueryResult(null);
 67→      try {
 68→        const start = performance.now();
 69→        const response = await fetch('/api/query', {
 70→          method: 'POST',
 71→          headers: { 'Content-Type': 'application/json' },
 72→          body: JSON.stringify({ sql }),
 73→        });
 74→        const elapsed = performance.now() - start;
 75→
 76→        if (!response.ok) {
 77→          const errorData = await response.json();
 78→          throw new Error(errorData.detail || 'Query execution failed');
 79→        }
 80→
 81→        const result = await response.json();
 82→        setQueryResult({
 83→          columns: result.columns,
 84→          rows: result.rows,
 85→          rowCount: result.rowCount,
 86→          executionTimeMs: elapsed,
 87→          resultType: result.resultType,
 88→        });
 89→        await refreshTables();
 90→      } catch (e) {
 91→        setError(e instanceof Error ? e.message : 'Query execution failed');
 92→      }
 93→    },
 94→    [refreshTables]
 95→  );
 96→
 97→  const handleTableClick = useCallback((tableName: string) => {
 98→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
 99→  }, []);
100→
101→  const handleTableDelete = useCallback(async (tableName: string) => {
102→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
103→    try {
104→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
105→        method: 'DELETE',
106→      });
107→      if (!response.ok) throw new Error('Failed to delete table');
108→      await refreshTables();
109→    } catch (e) {
110→      setError(e instanceof Error ? e.message : 'Failed to delete table');
111→    }
112→  }, [refreshTables, t]);
113→
114→  const appClass = [
115→    'app',
116→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
117→  ].filter(Boolean).join(' ');
118→
119→  const themeIcon = theme === 'dark' ? (
120→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
121→      <circle cx="12" cy="12" r="5" />
122→      <line x1="12" y1="1" x2="12" y2="3" />
123→      <line x1="12" y1="21" x2="12" y2="23" />
124→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
125→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
126→      <line x1="1" y1="12" x2="3" y2="12" />
127→      <line x1="21" y1="12" x2="23" y2="12" />
128→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
129→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
130→    </svg>
131→  ) : (
132→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
133→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
134→    </svg>
135→  );
136→
137→  return (
138→    <div className={appClass}>
139→      <div className="app__sidebar-wrapper">
140→        <Sidebar tables={tables} onTableClick={handleTableClick} onTableDelete={handleTableDelete} collapsed={sidebarCollapsed} onToggle={() => setSidebarCollapsed((prev) => !prev)} />
141→      </div>
142→      {agentOpen ? (
143→        <div className="app__agent-wrapper">
144→          <div className="app__header">
145→            <h1 className="app__title">{t('appTitle')}</h1>
146→            <div className="app__header-actions">
147→              <button
148→                className="app__lang-toggle"
149→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
150→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
151→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
152→              >
153→                {language === 'en' ? 'EN' : '中'}
154→              </button>
155→              <button
156→                className="app__theme-toggle"
157→                onClick={toggleTheme}
158→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
159→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
160→              >
161→                {themeIcon}
162→              </button>
163→              <button
164→                className="app__agent-toggle app__agent-toggle--active"
165→                onClick={handleAgentToggle}
166→              >
167→                {t('editorMode')}
168→              </button>
169→            </div>
170→          </div>
171→          <AgentPanel langfuseStatus={langfuseStatus} />
172→        </div>
173→      ) : (
174→        <div className="app__editor-wrapper">
175→          <div className="app__header">
176→            <h1 className="app__title">{t('appTitle')}</h1>
177→            <div className="app__header-actions">
178→              <button
179→                className="app__lang-toggle"
180→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
181→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
182→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
183→              >
184→                {language === 'en' ? 'EN' : '中'}
185→              </button>
186→              <button
187→                className="app__theme-toggle"
188→                onClick={toggleTheme}
189→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
190→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
191→              >
192→                {themeIcon}
193→              </button>
194→              <button
195→                className="app__agent-toggle"
196→                onClick={handleAgentToggle}
197→              >
198→                {t('agentMode')}
199→              </button>
200→            </div>
201→          </div>
202→          <div className="app__mode-header">
203→            <span className="app__mode-title">{t('editorMode')}</span>
204→          </div>
205→          <main className="app__main">
206→            <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
207→            <QueryEditor
208→              onExecute={handleQueryExecute}
209→              initialQuery={editorQuery}
210→            />
211→            {error && (
212→              <ErrorMessage message={error} onDismiss={() => setError(null)} />
213→            )}
214→            {queryResult?.resultType === 'markdown' ? (
215→              <ResultMarkdown result={queryResult} />
216→            ) : (
