174→        <div className="app__editor-wrapper">
175→          <div className="app__header">
176→            <h1 className="app__title">{t('appTitle')}</h1>
177→            <div className="app__header-actions">
178→              <button
179→                className="app__lang-toggle"
180→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
181→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
182→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
183→              >
184→                {language === 'en' ? 'EN' : '中'}
185→              </button>
186→              <button
187→                className="app__theme-toggle"
188→                onClick={toggleTheme}
189→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
190→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
191→              >
192→                {themeIcon}
193→              </button>
194→              <button
195→                className="app__agent-toggle"
196→                onClick={handleAgentToggle}
197→              >
198→                {t('agentMode')}
199→              </button>
200→            </div>
201→          </div>
202→          <div className="app__mode-header">
203→            <span className="app__mode-title">{t('editorMode')}</span>
204→          </div>
205→          <main className="app__main">
206→            <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
207→            <QueryEditor
208→              onExecute={handleQueryExecute}
209→              initialQuery={editorQuery}
210→            />
211→            {error && (
212→              <ErrorMessage message={error} onDismiss={() => setError(null)} />
213→            )}
214→            {queryResult?.resultType === 'markdown' ? (
215→              <ResultMarkdown result={queryResult} />
216→            ) : (
217→              <ResultsTable result={queryResult} />
218→            )}
219→          </main>
220→        </div>
221→      )}
222→    </div>
223→  );
224→}
