226→export default function App() {
227→  const [tables, setTables] = useState<TableInfo[]>([]);
228→  const [loading, setLoading] = useState(true);
229→  const [error, setError] = useState<string | null>(null);
230→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
231→
232→  const refreshTables = useCallback(async () => {
233→    try {
234→      const response = await fetch('/api/tables');
235→      if (!response.ok) throw new Error('Failed to fetch tables');
236→      const data = await response.json();
237→      setTables(data);
238→    } catch (e) {
239→      console.error('Failed to refresh tables:', e);
240→    }
241→  }, []);
242→
243→  useEffect(() => {
244→    (async () => {
245→      try {
246→        const response = await fetch('/api/health');
247→        if (!response.ok) throw new Error('Backend is not available');
248→        await refreshTables();
249→        try {
250→          const lfRes = await fetch('/api/langfuse/status');
251→          if (lfRes.ok) {
252→            setLangfuseStatus(await lfRes.json());
253→          }
254→        } catch {
255→          // Langfuse status fetch is non-critical
256→        }
257→      } catch (e) {
258→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
259→      } finally {
260→        setLoading(false);
261→      }
262→    })();
263→  }, [refreshTables]);
264→
265→  if (loading) {
266→    return <div className="app-loading">Connecting to backend...</div>;
267→  }
268→
269→  if (error) {
270→    return (
271→      <div className="app-error">Failed to connect: {error}</div>
272→    );
273→  }
274→
275→  return (
276→    <LanguageProvider>
277→      <ThemeProvider>
278→        <AgentProvider refreshTables={refreshTables}>
279→          <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
280→        </AgentProvider>
281→      </ThemeProvider>
282→    </LanguageProvider>
283→  );
284→}
