177→+++ b/frontend/src/LanguageContext.tsx
178→@@ -0,0 +1,60 @@
179→+import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react';
180→+import en from './i18n/en.json';
181→+import zhTW from './i18n/zh-TW.json';
182→+
183→+export type Language = 'en' | 'zh-TW';
184→+
185→+const translations: Record<Language, Record<string, string>> = {
186→+  'en': en,
187→+  'zh-TW': zhTW,
188→+};
189→+
190→+interface LanguageContextValue {
191→+  language: Language;
192→+  setLanguage: (lang: Language) => void;
193→+  t: (key: string, params?: Record<string, string | number>) => string;
194→+}
195→+
196→+const LanguageContext = createContext<LanguageContextValue | null>(null);
197→+
198→+function getInitialLanguage(): Language {
199→+  const stored = localStorage.getItem('language');
200→+  if (stored === 'en' || stored === 'zh-TW') return stored;
201→+  if (navigator.language.startsWith('zh')) return 'zh-TW';
202→+  return 'en';
203→+}
204→+
205→+export function LanguageProvider({ children }: { children: ReactNode }) {
206→+  const [language, setLanguageState] = useState<Language>(getInitialLanguage);
207→+
208→+  useEffect(() => {
209→+    document.documentElement.setAttribute('lang', language === 'zh-TW' ? 'zh-Hant' : 'en');
210→+    localStorage.setItem('language', language);
211→+  }, [language]);
212→+
213→+  const setLanguage = useCallback((lang: Language) => {
214→+    setLanguageState(lang);
215→+  }, []);
216→+
217→+  const t = useCallback((key: string, params?: Record<string, string | number>): string => {
218→+    let value = translations[language][key] ?? key;
219→+    if (params) {
220→+      for (const [paramKey, paramValue] of Object.entries(params)) {
221→+        value = value.replace(new RegExp(`\\{${paramKey}\\}`, 'g'), String(paramValue));
222→+      }
223→+    }
224→+    return value;
225→+  }, [language]);
226→+
227→+  return (
228→+    <LanguageContext.Provider value={{ language, setLanguage, t }}>
229→+      {children}
230→+    </LanguageContext.Provider>
231→+  );
232→+}
233→+
234→+export function useTranslation() {
235→+  const ctx = useContext(LanguageContext);
236→+  if (!ctx) throw new Error('useTranslation must be used within LanguageProvider');
237→+  return ctx;
238→+}
