230→export default function App() {
231→  const [tables, setTables] = useState<TableInfo[]>([]);
232→  const [loading, setLoading] = useState(true);
233→  const [error, setError] = useState<string | null>(null);
234→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
235→
236→  const refreshTables = useCallback(async () => {
237→    try {
238→      const response = await fetch('/api/tables');
239→      if (!response.ok) throw new Error('Failed to fetch tables');
240→      const data = await response.json();
241→      setTables(data);
242→    } catch (e) {
243→      console.error('Failed to refresh tables:', e);
244→    }
245→  }, []);
246→
247→  useEffect(() => {
248→    (async () => {
249→      try {
250→        const response = await fetch('/api/health');
251→        if (!response.ok) throw new Error('Backend is not available');
252→        await refreshTables();
253→        try {
254→          const lfRes = await fetch('/api/langfuse/status');
255→          if (lfRes.ok) {
256→            setLangfuseStatus(await lfRes.json());
257→          }
258→        } catch {
259→          // Langfuse status fetch is non-critical
260→        }
261→      } catch (e) {
262→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
263→      } finally {
264→        setLoading(false);
265→      }
266→    })();
267→  }, [refreshTables]);
268→
269→  if (loading) {
270→    return <div className="app-loading">Connecting to backend...</div>;
271→  }
272→
273→  if (error) {
274→    return (
275→      <div className="app-error">Failed to connect: {error}</div>
276→    );
277→  }
278→
279→  return (
280→    <LanguageProvider>
281→      <ThemeProvider>
282→        <AgentProvider refreshTables={refreshTables}>
283→          <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
284→        </AgentProvider>
285→      </ThemeProvider>
286→    </LanguageProvider>
287→  );
288→}
